import { Box, Widget, WidgetPair } from "cross-package-dep";

/** A member of each referenced shape, so the O7 templated name is read at three arities of use. */
export interface Panel {
    widget: Widget;
    boxed: Box<string>;
    pair: WidgetPair;
}

/** A referenced generic at a return position, applied to another referenced name. */
export declare function mount(widget: Widget): Box<Widget>;
